import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Welcome to SQL Power Hour","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),a={name:`index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="welcome-to-sql-power-hour" tabindex="-1">Welcome to SQL Power Hour <a class="header-anchor" href="#welcome-to-sql-power-hour" aria-label="Permalink to “Welcome to SQL Power Hour”">​</a></h1><p>Welcome to SQL Power Hour!</p><p>You were hired because you have the skills, knowledge, and potential to deliver great software. This program isn&#39;t here to question that or take you back to square one. Instead, it&#39;s an opportunity to sharpen your SQL skills, explore different approaches to solving problems, and build on the experience you already have.</p><h2 id="why-sql-power-hour" tabindex="-1">Why SQL Power Hour? <a class="header-anchor" href="#why-sql-power-hour" aria-label="Permalink to “Why SQL Power Hour?”">​</a></h2><p>SQL is more than a skill we list on our CVs or use to answer interview questions. It&#39;s a tool we rely on to build, maintain, and support real-world applications. Working with client projects means encountering different database structures, complex queries, unfamiliar business requirements, and situations where getting the right result is only part of the solution.</p><p>SQL Power Hour gives us a dedicated space to practise, challenge ourselves, and learn from one another. Through a series of practical exercises built around a shared database, we&#39;ll explore everything from writing straightforward queries to solving more complex data problems.</p><p>You might discover a new way to approach a familiar problem, revisit a concept you haven&#39;t used in a while, or learn a technique that makes your queries more effective. And that&#39;s the point: there&#39;s always room to grow, regardless of how much you already know.</p><h2 id="what-to-expect" tabindex="-1">What to Expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to “What to Expect”">​</a></h2><p>Each session focuses on a particular SQL topic, with exercises of varying difficulty. You&#39;ll work through practical problems, apply your knowledge, and have opportunities to compare approaches and discuss solutions.</p><p>Some exercises will be straightforward. Others will require a little more thought. The goal isn&#39;t simply to complete as many questions as possible, but to understand the problems you&#39;re solving and the reasoning behind your solutions.</p><p>The Bigger Picture</p><p>At the end of the day, we&#39;re not here just to write queries that work. We&#39;re here to become more confident, adaptable, and effective developers who can work with data in different environments and contribute meaningfully to the projects we support.</p><p>Bring the knowledge you already have, be open to learning something new, and don&#39;t be afraid to tackle a challenging problem.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};